{
  "method": "To determine the Weighted Average Cost of Capital (WACC), we use the formula: WACC = (Debt * Cost of Debt + Equity * Cost of Equity) / (Debt + Equity). When considering tax, the formula adjusts to: WACC = (Debt * Cost of Debt * (1 - Tax Rate) + Equity * Cost of Equity) / (Debt + Equity). Each component is weighted by its proportion of the total capital.",
   "calculations": [
      {"label": "WACC tax exempt", "expression": "(25000000 * 0.10 + 20000000 * 0.20) / (25000000 + 20000000)"},
      {"label": "WACC with 30% tax rate", "expression": "(25000000 * 0.10 * (1 - 0.30) + 20000000 * 0.20) / (25000000 + 20000000)"}
   ],
   "keyPoints": [
      "Identification of the correct WACC formula",
      "Application of the tax rate to the cost of debt",
      "Correct weighting of debt and equity costs by their respective proportions of total capital",
      "Separate calculation of WACC for tax-exempt and 30% marginal tax rate scenarios"
   ]
}
